class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid, int k) {
        int R = grid.size(), C = grid[0].size();
        vector<vector<int>> pref(R + 1, vector<int>(C + 1, 0));
        int ans = 0;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                pref[r + 1][c + 1] = grid[r][c] + pref[r][c + 1] + pref[r + 1][c] - pref[r][c];
                if (pref[r + 1][c + 1] <= k) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countSubmatrices(int[][] grid, int k) {
        int R = grid.length, C = grid[0].length;
        int[][] pref = new int[R + 1][C + 1];
        int ans = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                pref[r + 1][c + 1] = grid[r][c] + pref[r][c + 1] + pref[r + 1][c] - pref[r][c];
                if (pref[r + 1][c + 1] <= k) ans++;
            }
        }
        return ans;
    }
}

var countSubmatrices = function(grid, k) {
    const R = grid.length, C = grid[0].length;
    const pref = Array.from({ length: R + 1 }, () => new Array(C + 1).fill(0));
    let ans = 0;
    for (let r = 0; r < R; ++r) {
        for (let c = 0; c < C; ++c) {
            pref[r + 1][c + 1] = grid[r][c] + pref[r][c + 1] + pref[r + 1][c] - pref[r][c];
            if (pref[r + 1][c + 1] <= k) ans++;
        }
    }
    return ans;
};
